def block_compression(grid, in_w, out_w):
    """Apply block-based horizontal compression"""
    height = len(grid)
    output = [[8]*out_w for _ in range(height)]

    # Determine block sizes
    blocks = [in_w // out_w]
    remainder = in_w % out_w
    for i in range(remainder):
        blocks[0] += 1
    blocks = blocks + [in_w // out_w] * (out_w - len(blocks))

    print(f"Block sizes for {in_w}->{out_w}: {blocks}")

    col = 0
    for block_size in blocks:
        for c_in in range(col, min(col + block_size, in_w)):
            val = grid[0][c_in]  # just check first row values
            if val != 8:
                if output[0][col] == 8:
                    output[0][col] = val
        col += 1

    # Now do the full thing
    for r in range(height):
        col = 0
        for block_size in blocks:
            for c_in in range(col, min(col + block_size, in_w)):
                val = grid[r][c_in]
                if val != 8:
                    if output[r][col] == 8:
                        output[r][col] = val
            col += 1

    return output

